import{_ as l,o as t,c as r,a2 as o}from"./chunks/framework.Buc7gXeZ.js";const h=JSON.parse('{"title":"媒体上传与转码流","description":"分片直传、秒传哈希去重与自适应流媒体转码技术说明。","frontmatter":{"title":"媒体上传与转码流","description":"分片直传、秒传哈希去重与自适应流媒体转码技术说明。","order":22,"group":"guide"},"headers":[],"relativePath":"upload-transcode.md","filePath":"upload-transcode.md"}'),e={name:"upload-transcode.md"};function i(n,a,s,d,u,_){return t(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="媒体上传与转码流" tabindex="-1">媒体上传与转码流 <a class="header-anchor" href="#媒体上传与转码流" aria-label="Permalink to &quot;媒体上传与转码流&quot;">​</a></h1><p>MetaFusion 采用现代化的对象存储与分布式转码架构，确保大文件上传稳定可靠，并在各种设备上都能获得即时流畅的播放体验。</p><hr><h2 id="_1-分片断点直传" tabindex="-1">1. 分片断点直传 <a class="header-anchor" href="#_1-分片断点直传" aria-label="Permalink to &quot;1. 分片断点直传&quot;">​</a></h2><ul><li><strong>直接上传至存储桶</strong>：客户端直连 RustFS (S3 兼容高速对象存储集群)，不占用主 API 服务器带宽，上传速度不受网关性能瓶颈限制。</li><li><strong>分片与断点续传</strong>：大文件被智能拆分为多个分片并行上传。若遇网络抖动中断，重新选择同一文件即可自动从断点继续传输，无需从头重传。</li><li><strong>SHA-256 秒传去重</strong>：上传前在本地计算文件特征哈希。若平台存储中已存在相同二进制文件，系统将直接完成秒传复用，节省带宽与存储空间。</li></ul><hr><h2 id="_2-异步转码与多码率分发" tabindex="-1">2. 异步转码与多码率分发 <a class="header-anchor" href="#_2-异步转码与多码率分发" aria-label="Permalink to &quot;2. 异步转码与多码率分发&quot;">​</a></h2><p>文件上传成功后，系统工作节点会自动启动后台异步转码任务：</p><ul><li><strong>音频处理</strong>： <ul><li>母盘原档安全归档；</li><li>自动抽取元数据标签（ID3 / Vorbis Comments / 嵌入封面）；</li><li>自动生成 320kbps AAC/MP3 预览音频流与 100 点音频波形数据，供底栏播放器实时渲染。</li></ul></li><li><strong>视频处理</strong>： <ul><li>生成多码率自适应 HLS 流（.m3u8 切片），根据用户当前网络带宽自动平滑切换画质；</li><li>生成时间轴视频缩略图（雪碧图），支持播放进度条悬停快速预览。</li></ul></li><li><strong>图像与文档</strong>： <ul><li>自动压缩生成 WebP 高清缩略图与移动端自适应小图。</li></ul></li></ul><hr><h2 id="_3-安全与访问控制" tabindex="-1">3. 安全与访问控制 <a class="header-anchor" href="#_3-安全与访问控制" aria-label="Permalink to &quot;3. 安全与访问控制&quot;">​</a></h2><ul><li><strong>原档下载受控</strong>：只有登录认证用户可获取具备有效时限的临时下载签名 URL，防止未授权盗链与自动化滥用。</li><li><strong>预览流鉴权保护</strong>：所有流媒体切片均受到访问控制保护，确保平台资源安全可控。</li></ul>',12)])])}const p=l(e,[["render",i]]);export{h as __pageData,p as default};
